package ru.metro.objmodels.client;
import java.io.IOException;import java.util.*;import net.minecraft.client.*;import net.minecraft.client.gui.*;import net.minecraft.util.text.TextFormatting;import ru.metro.objmodels.ObjModels;import ru.metro.objmodels.common.ObjModelsRegistry;import ru.metro.objmodels.network.PlaceModelMessage;
public class GuiModels extends GuiScreen {
 private List<String> models=new ArrayList<>();private int selected=0,rotation=0,scroll=0;public static void open(){Minecraft.getMinecraft().displayGuiScreen(new GuiModels());}
 @Override public void initGui(){models=ObjModelsRegistry.names();buttonList.clear();buttonList.add(new GuiButton(1,width/2-100,height-52,60,20,"-90°"));buttonList.add(new GuiButton(2,width/2-35,height-52,70,20,"Повернуть"));buttonList.add(new GuiButton(3,width/2+40,height-52,60,20,"+90°"));buttonList.add(new GuiButton(4,width/2-100,height-27,200,20,"Поставить модель"));}
 @Override protected void actionPerformed(GuiButton b)throws IOException{if(b.id==1)rotation=(rotation+270)%360;if(b.id==3)rotation=(rotation+90)%360;if(b.id==2)rotation=(rotation+90)%360;if(b.id==4&&selected<models.size()){ObjModels.NETWORK.sendToServer(new PlaceModelMessage(models.get(selected),rotation));mc.displayGuiScreen(null);}}
 @Override protected void mouseClicked(int x,int y,int btn)throws IOException{if(y>40&&y<height-70){int i=(y-40)/22+scroll;if(i>=0&&i<models.size())selected=i;}super.mouseClicked(x,y,btn);}
 @Override public void drawScreen(int mx,int my,float pt){drawDefaultBackground();drawCenteredString(fontRenderer,"OBJ модели — выбор и поворот",width/2,14,0xffffff);if(models.isEmpty())drawCenteredString(fontRenderer,"Нет моделей. Добавьте config/obj/<имя>/model.obj",width/2,54,0xff7777);for(int i=scroll;i<Math.min(models.size(),scroll+Math.max(1,(height-120)/22));i++){int y=40+(i-scroll)*22;drawRect(width/2-115,y-3,width/2+115,y+17,i==selected?0xff526c8e:0xff252525);drawCenteredString(fontRenderer,models.get(i),width/2,y,0xffffff);}drawCenteredString(fontRenderer,"Поворот: "+rotation+"°",width/2,height-65,0xcccccc);super.drawScreen(mx,my,pt);}
 @Override public void handleMouseInput()throws IOException{super.handleMouseInput();int wheel=org.lwjgl.input.Mouse.getEventDWheel();if(wheel!=0)scroll=Math.max(0,Math.min(Math.max(0,models.size()-1),scroll+(wheel<0?1:-1)));}
 @Override public boolean doesGuiPauseGame(){return false;}
}
